import { USERS, expect, sample, test, uniqueName } from "../../fixtures";

test.describe("Vendor audit trail", () => {
  test(
    "audit events are listed oldest first with actor and action",
    { tag: "@AUD-01" },
    async ({ apiAs }) => {
      // Arrange: a signed-in member creates a vendor and uploads a W-9 for it.
      const member = await apiAs("member");
      const me = await (await member.get("/api/me")).json();

      const createResponse = await member.post("/api/vendors", {
        data: {
          name: uniqueName("Audit Vendor"),
          category: "services",
          contact_email: `audit-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@vendor.test`,
        },
      });
      expect(createResponse.status()).toBe(201);
      const vendor = await createResponse.json();

      const uploadResponse = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "w9",
          file: {
            name: "w9.pdf",
            mimeType: "application/pdf",
            buffer: Buffer.from("%PDF-1.4 audit trail test W-9"),
          },
        },
      });
      expect(uploadResponse.status()).toBe(201);
      const document = await uploadResponse.json();

      // Extraction runs asynchronously; wait for it to finish before reading the trail.
      await expect
        .poll(
          async () => {
            const response = await member.get(`/api/documents/${document.id}`);
            return (await response.json()).status;
          },
          { timeout: 60_000, intervals: [500, 1000, 2000] },
        )
        .toBe("extracted");

      // Act
      const auditResponse = await member.get(`/api/vendors/${vendor.id}/audit`);

      // Assert
      expect(auditResponse.status()).toBe(200);
      const trail = (await auditResponse.json()) as {
        items: Array<{
          id: number;
          action: string;
          actor: { id: string; name: string; email: string };
          at: string;
        }>;
      };

      const scenarioActions = ["vendor.created", "document.uploaded", "document.extracted"];
      const relevant = trail.items.filter((event) => scenarioActions.includes(event.action));
      expect(relevant.map((event) => event.action)).toEqual(scenarioActions);

      for (const event of relevant) {
        expect(event.actor.id).toBeTruthy();
        expect(event.actor.name).toBeTruthy();
        expect(event.actor.email).toBe(USERS.member);
        expect(event.actor.id).toBe(me.id);
        expect(Number.isNaN(Date.parse(event.at))).toBe(false);
      }

      // Oldest first: timestamps must not decrease along the trail.
      const times = trail.items.map((event) => Date.parse(event.at));
      for (let i = 1; i < times.length; i++) {
        expect(times[i]).toBeGreaterThanOrEqual(times[i - 1]);
      }
    },
  );
});
